nextflow_process {

    name "Test Process DEEPVARIANT_MAKEEXAMPLES"
    script "../main.nf"
    config "./nextflow.config"
    process "DEEPVARIANT_MAKEEXAMPLES"

    tag "deepvariant/makeexamples"
    tag "deepvariant"
    tag "modules"
    tag "modules_nfcore"

    test("homo_sapiens - [bam, bai] - fasta - fai") {
        when {

            process {
                """
                input[0] = [
                    [ id:'test', single_end:false ], // meta map
                      file(params.modules_testdata_base_path + '/genomics/homo_sapiens/illumina/bam/test.paired_end.sorted.bam', checkIfExists: true),
                      file(params.modules_testdata_base_path + '/genomics/homo_sapiens/illumina/bam/test.paired_end.sorted.bam.bai', checkIfExists: true),
                      []
                ]
                input[1] = [
                    [ id:'genome'],
                      file(params.modules_testdata_base_path + '/genomics/homo_sapiens/genome/genome.fasta', checkIfExists: true)
                ]
                input[2] = [
                    [ id:'genome'],
                      file(params.modules_testdata_base_path + '/genomics/homo_sapiens/genome/genome.fasta.fai', checkIfExists: true)
                ]
                input[3] = [
                    [],[]
                ]
                input[4] = [
                    [],[]
                ]
                input[5] = false
                """
            }
        }

        then {
            assertAll(
                { assert process.success },

                { assert process.out.examples[0][0] == [id:'test', single_end:false] },
                { assert process.out.gvcf[0][0] == [id:'test', single_end:false] },
                { assert process.out.examples[0][1].size() == 4 },
                { assert snapshot(
                    process.out.examples[0][1].collect { file(it).name }
                ).match("test1-examples-filenames") },
                { assert process.out.gvcf[0][1].size() == 2 },
                { assert snapshot(process.out.versions_deepvariant).match("test1-versions") },
                { assert snapshot(
                    process.out.gvcf[0][1].collect { file(it).name }
                ).match("test1-gvcf-filenames") },
                { assert process.out.read_phase_inputs[0][0] == [id:'test', single_end:false] },
                { assert process.out.read_phase_inputs[0][1] == [] }
            )
        }
    }

