                { assert process.out.read_phase_inputs[0][0] == [id:'test', single_end:false] },
                { assert process.out.read_phase_inputs[0][1].size() == 2 },
                { assert snapshot(
                    process.out.read_phase_inputs[0][1].collect { file(it).name }
                ).match("test4-read-phase-inputs-filenames") }
            )
        }
    }

    test("stub") {

        options "-stub"

        when {

            process {
                """
                input[0] = [
                    [ id:'test', single_end:false ], // meta map
                      file(params.modules_testdata_base_path + '/genomics/homo_sapiens/illumina/bam/test.paired_end.sorted.bam', checkIfExists: true),
