                ]
                input[2] = [
                    [ id:'genome'],
                      file(params.modules_testdata_base_path + '/genomics/homo_sapiens/genome/genome.fasta.fai', checkIfExists: true)
                ]
                input[3] = [
                    [],[]
                ]
                input[4] = [
                    [],[]
                ]
                input[5] = false
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert process.out.gvcf[0][0] == [id:'test', single_end:false] },
                { assert process.out.examples[0][1].size() == 4 },
                { assert snapshot(
                    process.out.examples[0][1].collect { file(it).name }
                ).match("test5-examples-filenames") },
                { assert process.out.gvcf[0][1].size() == 2 },
                { assert snapshot(process.out.versions_deepvariant).match("test5-versions") },
                { assert snapshot(
                    process.out.gvcf[0][1].collect { file(it).name }
                ).match("test5-gvcf-filenames") }
            )
        }
    }
}

process {
    withName: "DEEPVARIANT_MAKEEXAMPLES" {
        cpus = 2 // The number of output files is determined by cpus - keep it the same for tests
        ext.args = '--checkpoint "/opt/models/wgs" --call_small_model_examples --small_model_indel_gq_threshold "30" --small_model_snp_gq_threshold "25" --small_model_vaf_context_window_size "51" --trained_small_model_path "/opt/smallmodels/wgs/model.keras"'
    }
}

process {
    withName: "DEEPVARIANT_MAKEEXAMPLES" {
        ext.args = '--checkpoint "/opt/models/pacbio" --call_small_model_examples --small_model_indel_gq_threshold "30" --small_model_snp_gq_threshold "25" --small_model_vaf_context_window_size "51" --trained_small_model_path "/opt/smallmodels/pacbio/model.keras"'
    }
    withName: "DEEPVARIANT_CALLVARIANTS" {
        ext.args = '--checkpoint "/opt/models/pacbio"'
    }

    // This configures RUNDEEPVARIANT, which is used as a reference for the correct test output
    withName: DEEPVARIANT_RUNDEEPVARIANT {
         ext.args = '--model_type=PACBIO '
         ext.prefix = { "${meta.id}_out" }
     }
}
